inline bool enc_pin_irq(int pin, const char* bloque) {
    bool valido = true;
#if defined(__AVR_ATmega328P__) || defined(__AVR_ATmega168__)
    valido = pin == 2 || pin == 3;
#endif
#ifdef NOT_AN_INTERRUPT
    valido = valido && digitalPinToInterrupt(pin) != NOT_AN_INTERRUPT;
#endif
    if (!valido) {
        rb_fail(bloque, "Un pin del encoder no tiene interrupción; cámbialo (en UNO/Nano solo D2 y D3)");
    }
    return valido;
}
