inline void enc_configurar(int inicio, const enc_fila_t* filas, int cantidad, const String& modo, const char* bloque) {
    if (inicio < 0 || cantidad < 1 || inicio + cantidad > 6) { rb_fail(bloque, "Configura como máximo 6 encoders"); return; }
    int factor = modo == "x2" ? 2 : 4;
    // Valida todas las filas antes de instalar interrupciones.
    for (int i = 0; i < cantidad; i++) {
        const enc_fila_t& f = filas[i];
        if (enc_estado[inicio + i].activo) { rb_fail(bloque, "Configura los encoders una sola vez al iniciar"); return; }
        if (!f.nombre[0]) { rb_fail(bloque, "Pon nombres distintos y no vacíos a los encoders"); return; }
        if (!(f.ppr > 0) || !(f.red > 0) || !(f.diam > 0) || !isfinite(f.ppr * f.red * factor) || !isfinite(f.diam)) {
            rb_fail(bloque, "PPR, reducción y diámetro deben ser positivos y finitos"); return;
        }
        if (!enc_pin_irq(f.a, bloque) || (factor == 4 && !enc_pin_irq(f.b, bloque))) return;
        if (f.a == f.b) { rb_fail(bloque, "Los pines de los encoders no pueden repetirse"); return; }
        for (int j = 0; j < 6; j++) if (enc_estado[j].activo) {
            if (!strcmp(f.nombre, enc_estado[j].nombre)) { rb_fail(bloque, "Pon nombres distintos y no vacíos a los encoders"); return; }
            if (f.a == enc_estado[j].a || f.a == enc_estado[j].b || f.b == enc_estado[j].a || f.b == enc_estado[j].b) {
                rb_fail(bloque, "Los pines de los encoders no pueden repetirse"); return;
            }
        }
        for (int j = 0; j < i; j++) {
            if (!strcmp(f.nombre, filas[j].nombre)) { rb_fail(bloque, "Pon nombres distintos y no vacíos a los encoders"); return; }
            if (f.a == filas[j].a || f.a == filas[j].b || f.b == filas[j].a || f.b == filas[j].b) {
                rb_fail(bloque, "Los pines de los encoders no pueden repetirse"); return;
            }
        }
    }
    for (int i = 0; i < cantidad; i++) {
        int slot = inicio + i;
        const enc_fila_t& f = filas[i];
        enc_t& e = enc_estado[slot];
        e.a = f.a; e.b = f.b; e.nombre = f.nombre;
        e.signo = 1;
        e.modo = factor; e.cpr = f.ppr * f.red * factor; e.diam = f.diam;
        pinMode(e.a, INPUT_PULLUP);
        pinMode(e.b, INPUT_PULLUP);
        e.previo = (digitalRead(e.a) ? 2 : 0) | (digitalRead(e.b) ? 1 : 0);
        e.activo = true;
        enc_reiniciar(slot + 1, bloque);
        attachInterrupt(digitalPinToInterrupt(e.a), enc_isrs_a[slot], CHANGE);
        if (factor == 4) attachInterrupt(digitalPinToInterrupt(e.b), enc_isrs_b[slot], CHANGE);
    }
}
inline double enc_vueltas(int n, const char* bloque) {
    long cuentas = enc_cuentas(n, bloque);
    return enc_control(n, bloque) ? cuentas / enc_estado[n - 1].cpr : 0;
}
inline double enc_distancia(int n, const String& unidad, const char* bloque) {
    double vueltas = enc_vueltas(n, bloque);
    if (!enc_control(n, bloque)) return 0;
    return vueltas * 3.141592653589793 * enc_estado[n - 1].diam / (unidad == "cm" ? 10.0 : 1.0);
}
inline double enc_velocidad(int n, const String& unidad, const char* bloque) {
    if (!enc_control(n, bloque)) return 0;
    enc_t& e = enc_estado[n - 1];
    long cuentas = enc_cuentas(n, bloque);
    unsigned long ahora = micros();
    unsigned long dt = ahora - e.tiempo;
    if (dt >= 20000UL) {
        long diferencia = (long)((unsigned long)cuentas - (unsigned long)e.muestra);
        e.rps = (double)diferencia / e.cpr * 1000000.0 / dt;
        e.muestra = cuentas; e.tiempo = ahora;
    }
    return unidad == "rpm" ? e.rps * 60.0 : e.rps * 3.141592653589793 * e.diam / 10.0;
}
inline void enc_sentido(int n, const String& sentido, const char* bloque) {
    if (!enc_control(n, bloque)) return;
    enc_t& e = enc_estado[n - 1];
#if defined(ARDUINO_ARCH_ESP32)
    portENTER_CRITICAL(&enc_mux);
#else
    noInterrupts();
#endif
    e.signo = sentido == "invertido" ? -1 : 1;
    // Conserva las cuentas y reinicia solo la muestra de velocidad.
    e.muestra = e.cuentas;
    e.tiempo = micros();
    e.rps = 0;
#if defined(ARDUINO_ARCH_ESP32)
    portEXIT_CRITICAL(&enc_mux);
#else
    interrupts();
#endif
}

