enc_cuenta = array('l', [0] * 6)
enc_previo = bytearray(6)
enc_modo = bytearray(6)
enc_invertido = bytearray(6)
enc_tabla = bytes((0, 1, 255, 0, 255, 0, 0, 1, 1, 0, 0, 255, 0, 255, 1, 0))
enc_a = [None] * 6
enc_b = [None] * 6
enc_estado = [None] * 6
enc_handlers = [None] * 6

# Viper mantiene la suma en 32 bits nativos, sin crear enteros grandes en la IRQ.
@micropython.viper
def enc_flanco(i: int):
    actual = (int(enc_a[i].value()) << 1) | int(enc_b[i].value())
    previo = ptr8(enc_previo)
    modo = ptr8(enc_modo)
    invertido = ptr8(enc_invertido)
    tabla = ptr8(enc_tabla)
    cuentas = ptr32(enc_cuenta)
    paso = 0
    if modo[i] == 4:
        paso = int(tabla[(previo[i] << 2) | actual])
        if paso == 255:
            paso = -1
    else:
        paso = 1 if (actual >> 1) == (actual & 1) else -1
    if invertido[i]:
        paso = 0 - paso
    previo[i] = actual
    cuentas[i] = cuentas[i] + paso

def enc_handler(i):
    def handler(pin):
        enc_flanco(i)
    return handler

def enc_control(n, bloque):
    if n < 1 or n > 6 or enc_estado[n - 1] is None:
        rb_fail(bloque, "Configura los encoders al iniciar")
    return enc_estado[n - 1]

def enc_cuentas(n, bloque):
    enc_control(n, bloque)
    irq = machine.disable_irq()
    try:
        return enc_cuenta[n - 1]
    finally:
        machine.enable_irq(irq)

def enc_reiniciar(n, bloque):
    estado = enc_control(n, bloque)
    irq = machine.disable_irq()
    try:
        enc_cuenta[n - 1] = 0
        estado[2] = 0
        estado[3] = time.ticks_us()
        estado[4] = 0.0
    finally:
        machine.enable_irq(irq)

def enc_todos(bloque):
    if not any(e is not None for e in enc_estado):
        rb_fail(bloque, "Configura los encoders al iniciar")
    for i in range(6):
        if enc_estado[i] is not None:
            enc_reiniciar(i + 1, bloque)

def enc_configurar(inicio, filas, modo, bloque):
    if inicio < 0 or not filas or inicio + len(filas) > 6:
        rb_fail(bloque, "Configura como máximo 6 encoders")
    factor = 2 if modo == "x2" else 4
    nombres = [e[5] for e in enc_estado if e is not None]
    pines = [p for e in enc_estado if e is not None for p in e[6:8]]
    for i, (nombre, a, b, ppr, red, diam) in enumerate(filas):
        if enc_estado[inicio + i] is not None:
            rb_fail(bloque, "Configura los encoders una sola vez al iniciar")
        if not nombre.strip() or nombre in nombres:
            rb_fail(bloque, "Pon nombres distintos y no vacíos a los encoders")
        if not (ppr > 0 and red > 0 and diam > 0 and math.isfinite(ppr * red * factor) and math.isfinite(diam)):
            rb_fail(bloque, "PPR, reducción y diámetro deben ser positivos y finitos")
        if a == b or a in pines or b in pines:
            rb_fail(bloque, "Los pines de los encoders no pueden repetirse")
        nombres.append(nombre)
        pines.extend((a, b))
    for i, (nombre, a, b, ppr, red, diam) in enumerate(filas):
        slot = inicio + i
        enc_a[slot] = machine.Pin(a, machine.Pin.IN, machine.Pin.PULL_UP)
        enc_b[slot] = machine.Pin(b, machine.Pin.IN, machine.Pin.PULL_UP)
        enc_modo[slot] = factor
        enc_invertido[slot] = 0
        enc_previo[slot] = (enc_a[slot].value() << 1) | enc_b[slot].value()
        enc_estado[slot] = [ppr * red * factor, diam, 0, time.ticks_us(), 0.0, nombre, a, b]
        enc_reiniciar(slot + 1, bloque)
        enc_handlers[slot] = enc_handler(slot)
        trigger = machine.Pin.IRQ_RISING | machine.Pin.IRQ_FALLING
        enc_a[slot].irq(trigger=trigger, handler=enc_handlers[slot])
        if factor == 4:
            enc_b[slot].irq(trigger=trigger, handler=enc_handlers[slot])

def enc_vueltas(n, bloque):
    return enc_cuentas(n, bloque) / enc_control(n, bloque)[0]

def enc_distancia(n, unidad, bloque):
    return enc_vueltas(n, bloque) * math.pi * enc_control(n, bloque)[1] / (10 if unidad == "cm" else 1)

def enc_velocidad(n, unidad, bloque):
    estado = enc_control(n, bloque)
    cuentas = enc_cuentas(n, bloque)
    ahora = time.ticks_us()
    dt = time.ticks_diff(ahora, estado[3])
    if dt >= 20000:
        diferencia = ((cuentas - estado[2] + 0x80000000) & 0xffffffff) - 0x80000000
        estado[4] = diferencia / estado[0] * 1000000 / dt
        estado[2] = cuentas
        estado[3] = ahora
    return estado[4] * (60 if unidad == "rpm" else math.pi * estado[1] / 10)

def enc_sentido(n, sentido, bloque):
    estado = enc_control(n, bloque)
    irq = machine.disable_irq()
    try:
        enc_invertido[n - 1] = sentido == "invertido"
        estado[2] = enc_cuenta[n - 1]
        estado[3] = time.ticks_us()
        estado[4] = 0.0
    finally:
        machine.enable_irq(irq)

